// ===== KONFIGURASI =====
const DEMO = false;   // true = threshold diturunkan supaya alert pasti muncul. Ubah ke false setelah demo.

const d = JSON.parse($input.first().json.stdout);
const T = DEMO
  ? { cpu: 1, diskFree: 25, ram: 30, licenseDays: 90 }
  : { cpu: 85, diskFree: 15, ram: 85, licenseDays: 15 }; // Batas aman dinaikkan supaya tidak gampang trigger gagal

const issues = [];
if (d.cpu >= T.cpu) issues.push(`CPU tinggi: ${d.cpu}% (batas ${T.cpu}%)`);
if (d.disk_free < T.diskFree) issues.push(`Disk sisa ${d.disk_free}% (min ${T.diskFree}%)`);

// PERBAIKAN VALIDASI RAM:
// Jika d.ram di PowerShell Anda adalah "RAM Terpakai (Used)", naikkan batasan ke 85% atau 90%.
if (d.ram > T.ram) issues.push(`RAM ${d.ram}% (maks ${T.ram}%)`);

if (d.net !== 'Connected') issues.push('Koneksi timeout');
if (d.svc !== 'Running') issues.push(`Service ${d.svc} (Down)`);
if (d.errors > 0 || d.warnings > 0) issues.push(`${d.errors} error, ${d.warnings} warning dalam 1 jam terakhir`);

const daysLeft = Math.floor((new Date(d.license_expiry) - new Date()) / 86400000);
if (daysLeft < T.licenseDays) issues.push(`License expire ${daysLeft} hari lagi`);

const prompt = `Kamu adalah engineer monitoring server. Berikut hasil health check:

Metrik: CPU ${d.cpu}%, Disk free ${d.disk_free}%, RAM ${d.ram}%, Network ${d.net}, Service Spooler: ${d.svc}
Masalah terdeteksi: ${issues.join('; ')}
Potongan log (1 jam terakhir): ${d.logs || '(kosong)'}

Tugas: (1) rangkum masalah dalam 2 kalimat, (2) kemungkinan penyebab, (3) langkah troubleshooting berurutan beserta command-nya (Windows/PowerShell).
Gunakan nama service "Spooler" di command, jangan pakai placeholder.
Jawab singkat dalam bahasa Indonesia, tanpa markdown.`;

const aiBody = { contents: [{ parts: [{ text: prompt }] }] };

return [{ json: { ...d, license_days_left: daysLeft, issues, hasIssue: issues.length > 0, aiBody } }];

